using DocumentFormat.OpenXml.Packaging;
using System.IO;
using System.Windows;
using Word = DocumentFormat.OpenXml.Wordprocessing;

namespace LabFilp
{
    public class Attachment
    {
        public string Title { get; set; }
        public string Text { get; set; }
    }

    public partial class MainWindow : Window
    {
        private List<Attachment> _attachments = new List<Attachment>();

        public MainWindow()
        {
            InitializeComponent();
            LstApplications.ItemsSource = _attachments;
        }

        private void BtnAddApp_Click(object sender, RoutedEventArgs e)
        {
            string appTitle = TxtAppTitle.Text.Trim();

            if (string.IsNullOrWhiteSpace(appTitle))
            {
                MessageBox.Show("Пожалуйста, введите заголовок для приложения!", "Ошибка", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            bool isDuplicate = _attachments.Any(a => a.Title.Equals(appTitle, StringComparison.OrdinalIgnoreCase));
            if (isDuplicate)
            {
                MessageBox.Show($"Приложение с заголовком «{appTitle}» уже есть в списке! Придумайте другое название.",
                                "Дублирование заголовка", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            int nextIndex = _attachments.Count + 1;
            string generatedText = "";

            if (nextIndex == 1)
            {
                generatedText = "{{IO}}! Я всё хотел спросить, а что мы с парниками делать будем? Ведь подпорки ещё прошлый год гнилые были, а нынче я потрогал, так они все попрели — одна труха, так что плёнку не выдержат. Я думаю надо б попросить Серёжу привезти трубок таких и из них я б подпорок напилил, а после мы б их проволокою скрутили и стояло бы хорошо, хоть сто лет. А эти не выдержат ни за что, ещё бы, ведь плёнка она и от ветра заиграть может и опять же когда дождь пойдёт — раз, и вода вверху скопилась, он и повалился. Так что я думаю, что трубки это оптимальный варьянт. А огород уже протаял, я вдоль грядок ходил, они всё в норме и клубника и всё остальное. Я думаю мы картошку в этом году в заду посадим, это возле туалета, где подсолнух и горох росли. Там и почва хорошая, а у забора пусть редиска, да салат, да разная морковка. А картофелю там самый раз будет, он солнце любит, а там опять же мы ведь бузину повырубили, так что солнца хоть отбавляй. Ещё я как только пришёл, сразу в погреб полез поглядеть как там не натекло, но там всё было в норме — вода есть, но немного, не то что в позапрошлом году, когда и слезть то некуда было! А в этом всё нормально — на три пальца внизу, в ложбине, а к мешкам и не подобралась — все сухие. Так что о погребе вы не волнуйтесь. А после я на тераске семена смотрел и опять всё нормально — картошка сухая, тюльпаны и гладиолусы ваши тоже. {{IO}}! Как ваше здоровье? Как Людмила Степановна? Как там Саша поживает? Вы мне пишите чаще, и передавайте всем приветы. Так что жду от вас писем и Ц.У.\r\nДо свидания.\r\n";
            }
            else if (nextIndex == 2)
            {
                generatedText = "Дорогой {{IO}}\r\nЗдравствуйте! Как вы там все поживаете, как Людмила Степановна, как её здоровье, как Сашенька? Я живу тут нормально, здоровье ничего, нога не болит, ну и слава Богу. Начал я разбираться на тераске, {{IO}}, и понял, что зря мы войлок положили на низ, а сверху тогда навалили ящики. Там снизу впадина, а сверху-то крыша течёт и по полу к этой впадине вода шла, а там и скапливалась. А войлок он её впитал, и теперь я как нажал — а он как губка — весь водой напитался! Вот плохо как. Это мы с вами ошиблись. Но ничего, я верх разобрал и стал потихоньку их вытаскивать и на улицу выносить. Сначала было хотел кое-где разложить, а потом подумал — а крыша-то пустая стоит! И сухо там давно и по лесенке мне удобно. Взял и туда весь войлок затащил, разложил с нашей стороны, чтоб с дороги не очень в глаза бросалось и пусть сохнет. Я думаю что ничего ему не сделается — посохнет и всё будет нормально. Это ведь войлок, а не что нибудь. А после я за тачку принялся. Там колесо хорошее, но ручки никуда не годные, мы тогда ещё с ними намучились. Я их оторвал, пазы прочистил, две новые вытесал и приладил — любо-дорого посмотреть. Теперь возить будет — хоть куда, так что новую покупать, как Вера предлагала — не за чем, что ж это — хорошие вещи бросать? Там же колесо нормальное, чугунное и кузов целый, не развалился, да и вы тогда говорили что тачка хорошая, вместительная, а Вера говорит — новую. Как же новую достанешь? Я их сроду на складе не видел. Да вот, теперь про склад. Ездил опять и опять мимо — ребят моих не было, а сидел какой-то старик заспанный. И опять ничего — ни двадцатки, ни рубироида, ни дсп. Единственно что хорошо — цемент завезли и я прямо два мешка взял сходу. Это дело нужное, {{IO}}, никогда не пропадёт, а фундамент в сарае всё-таки надо делать каменный. Это я спорить готов с кем угодно. Там ведь низина и каждую весну вода по щиколку, он и подгнил-то от этого. На сухом месте он бы ещё десять лет простоял, а там в низине спрел вон как. А новый деревянный ставить — всё одно что деньги на ветер — всё равно сгниёт также, и оглянуться не успеем. Так что хоть вы и про деревянный говорили, а я вам точно говорю — это пустое дело, {{IO}}. Вы человек городской, а я с этим давно дело имею и точно говорю — каменный фундамент поставим — нас с вами перестоит и внуков наших. А кирпич я достану, это не волнуйтесь. Его немного надо, тут стройка в Киселёвке — там договориться раз плюнуть. Они за тридцатку машину белого кирпича привезут. Так что вы не волнуйтесь на этот счёт — всё будет в норме, а каменщика я найду, тут работяг хватает. Ему и работы-то на неделю не больше — поколенный фундамент. Зато сарай будет отличный. {{IO}}! Вы напишите мне как Саша закончил, интересно всё-таки. Теперь в вашей семье третий человек с высшим образованием будет. Это очень хорошо. Так что пишите, и про сарай не волнуйтесь. А Людмиле Степановне огромный привет и поклон.\r\nПишите, не забывайте.\r\nДо свидания.";
            }
            else if (nextIndex == 3)
            {
                generatedText = "Здравствуйте дорогие {{IO}}, Людмила Степановна и Саша!\r\nЯ живу нормально, здоровье хорошее. А как вы поживаете? Как ваши дела, как здоровье? Как встретили Первомай? Я вас ещё раз поздравляю с Праздником, желаю здоровья, счастья и всех благ. Получили вы мою открытку? А я от Маши получил письмо и очень обрадовался — она пишет, что Саша защитил диплом на пять. Это очень хорошо, так что поздравляю его от всего сердца и желаю чтобы он как и отец старался добиться высоких показателей в науке и технике. А вам, {{IO}} я желаю крепкого здоровья и всех всех благ. Мы тут Первомай отмечали с соседом Семёном Петровичем и его шурином Сергеем. Они уже вскопали у себя и хотят кое что посадить, так что у них образцовое хозяйство. А с ними мы немного выпили, посидели, потом послушали радио, а Семён Петрович мне рассказал как он достал электропилу. Её ведь не купишь нигде. А у него друг работал на базе, а там были, они разные институты снабжали. И вот он ему две поллитры и жена шесть батонов копчёной колбасы достала, а он им пилу списал. А пила отличная — с протектором, режет здорово, он мне показал, и говорит, что если нужно — в любой момент зайти можно и взять. Он мужик хороший, он и рубироид предлагал, но я отказался, что уж нам совсем побираться. Рубироид я достану, а вот пила — это дело. Мы ему поллитру поставим, он мужик хороший, пилу даст и тогда нам всё ни по чём — всё разрежем в момент. А ещё, {{IO}}, я начал копать помаленьку и хорошо пошло, земля уж не мокрая и я уголок возле туалет вскопал, не вспотел даже! И нога не болит, слава Богу. Вскопал, а после пошёл клубнику пообгрёб, расчистил, а там уж зелёные росточки так и прут! Клубника отличная, новая гряда прижилась, так что и в этом году, Бог даст будет много. А вот парники — плохо дело. Я палки снял, поломал и сжёг — чего им преть. А трубки точно будут это мне Семён Петрович обещал, я заплачу. А трубки для парников — в самый раз пойдут — их проволокой скрепить и натягивай хоть что — всё выдержит, и парники будут отличные. Вот чего ещё нет — это торфа, {{IO}}. Это дело нешуточное. Торф нам и под огурцы и под помидоры нужен, да и просто сажать без него — плохо. Я у соседей поспрашивал, они говорят что будут возить скоро, только караулить надо. Помните как прошлый год, только мы с вами приехали и машина подъехала! Как по заказу. А сегодня что-то не везут никому. А навоз в яме лежит нормально. И много, правильно вы тогда машину целую взяли, делить не стали. Правильно, он разойдётся в момент — огурцы, помидоры, а под яблоньки, а крыжовник, и на осень раскидать — всё уйдёт. Так что с навозом всё нормально, а вот торф надо доставать, никуда не денешься. {{IO}}, мне Маша написала про Николая и про ту историю всё подробно, всё как случилось. Прямо скажу — это очень плохо с его стороны так вести с таким заслуженным человеком, а главное — пожилым. Ведь мы ему в отцы годимся, а он так себя ведёт, как шпана подзаборная. Я ему тогда ещё когда мы собрались по поводу террасы у Любани, помните? И он так вошёл прямо как барин, расселся и начал меня учить уму разуму, меня пожилого человека, да я ему в отцы гожусь, а его сыну — в деды, а он мне мораль читает. Я ему и сказал тогда, не учи учёных, а тераску всё равно делить не будем. Так что вы не волнуйтесь, это всё пусть они брешут, а только всё останется по прежнему. {{IO}}! Я поздравляю вас с Днём Победы, потому как может скоро не напишу. Поздравляю и желаю здоровья, счастья, творческих успехов.\r\nПишите, не забывайте.\r\nДо свидания.";
            }
            else
            {
                generatedText = "Здравствуйте дорогие {{IO}}, Людмила Степановна и Саша! Пишет вам бывший сержант шестого отдельного артиллерийского полка и поздравляет вас всех с праздником Днём Победы! Желаю, чтобы никогда больше никто из вас не видел ужасов войны, чтобы небо наше было чистым и мирным, чтобы все были счастливы и жили в мире. А ещё желаю здоровья, счастья, мира! Мы тут живём хорошо, и я вот, {{IO}}, вспомнил Великую Отечественную. Вы наверно тоже её помните, но я вот вспомнил очень хорошо сейчас, когда вся наша Страна празднует этот праздник. Этот час нам никогда не забыть, {{IO}}, вы его тоже помните хорошо, так как вы тоже были опалены этим адским огнём, который пожёг всю нашу Страну. Ваш отец погиб в первые дни, а вы пошли добровольцем, хотя и имели возможность не воевать, потому что были ценным человеком — учёным. И были контужены и попали в госпиталь, а после работали в тылу, крепя оборону нашей Родины, и сделали ряд важных изобретений, которые помогли сломать хребет фашизму. А я, {{IO}}, пошёл попозже, так как мне было ещё шестнадцать, а мне сказали — погоди. И после через два года попал в самое пекло, а после прошёл всё — всю войну, до самого Берлина и даже возле рейхстага был и снялся с ребятами. Был ранен в голову — легко, а в ногу осколочным задело и хоть и вынули девять осколков, всё равно, как непогода — болит, ноет, спать не даёт. Но сейчас погода отличная — солнышко, тепло, я уже вскопал много чего — земля лёгкая. Начал я от того что тогда вскопал возле туалета и так разошёлся — прямо чуть не до лавочки! А главное лопата что надо, острая, роется на полный штык легко, работал два дня напролёт. А сегодня вечером начал с сараем разбираться. Всё барахло Верино выгреб на солнце — пусть посохнет, а то так не сгорит, только дымить будет. А за одно уж и стал доски гнилые отдирать, чтобы время не терять, а они главное почти что сами отлетают, и так всё на соплях держалось. Отодрал сзаду все доски и представьте себе — ни одной путёвой! Всё — труха трухой! Во как, что значит низина! А если б стоял справа у забора — ещё бы десять лет простоял. И когда новый будем строить, {{IO}}, я это точно говорю — фундамент надо кирпичный делать, никакой другой. Если деревянный низ будет — к чёрту попреет опять. А так по колено кирпича, а после доски, и он нас вами перестоит и внуков. Я доски сразу в угол и сложил, чтоб тоже как подсохнут, так и запалить, а сверху барахло Верино. И пусть не обижается, а Николаю я и так написать могу — сожгём к чёрту всё, чтобы участок не захламляли. Они и помогать-то не помогают, а всё разговоры разводят — нет чтоб щас вот приехать и помочь. Николай он только футбол целыми днями слушает, ему покойный Виктор Георгиевич говорит бывало, ну что ты ерунду, я извиняюсь, эту слушаешь, лучше б книгу хорошую прочёл, а он всё слушает и слушает, вот и дослушался — как грузчиком пошёл, так и работает. Это не то что вы или Саша. Это люди не интелегенты, хамло порядочное. А вы с ним ещё так вежливо говорите, да он и разговору то не стоит, не то что чего. Это хамы известные и Вера ему под стать. Они приедут, когда клубника, да помидоры, да всё плодоносит. А мы ведь люди добрые, что вы с Людмилой Степановной, что мы с Машей. Мы и мухи не обидим — пожалуйста, бери, ешь, я не загораживаю, я и сам принесу — на, бери, если мы в родстве. Но только люди они не простые — с говницом. Нет чтобы и к нам с вами с открытой душой, нет, так у них не заведено. А потому что Виктор Георгиевич покойный добрым был, тихим, а они на него с детства орать приучились, вот как теперь. А я бы на его месте взял бы по морде тогда давал побольше, авось поумнели. А теперь конечно, что ж делать, он вон битюг какой — накачался, да от пива разнесло его. Молодой, а брюхо больше моего. А ещё гонору хоть отбавляй. Далась им эта тераска. Не они же строили, а я с Виктором Георгиевичем покойным, а деньги вы дали. А они — делить. Да и чего там делить — шестнадцать метров! Курам на смех! Как делить? Перегородкой? А входить как? Значит — два крыльца делать? Так это в копеечку влетит. А потом — терасса хорошая, а будет что — конура мне и конура им. А вы? Что ж и на вас тогда надо? Они же этого ничего не понимают, бестолковые, им лишь бы разделить. А тут ещё подумать надо о верхе, может верх надо б отстроить, а то что ж у всех дети, им тоже приехать куда-то надо, а они — тераска. Не в тераске дело, это я им тогда говорил. А главное, вы думаете Николай будет строить? Никогда! Он деньги даст, а ты паши на него — с плотниками договаривайся, доски доставай, вози их. А они прикотят — клубнику есть и загорать. Вот и всё. А я тут — фронтовик с больной ногой горби на них, а Маша окучивает картошку целыми днями, да пропалывает, а они — на пожалуста, вы вырастили, а мы сожрём. Я не жалею, {{IO}}, я никому никогда попрёки не выговаривал, но только что ж это получается такое — почему такая несправедливость? Что мы — хуже их? Так что, вы {{IO}} с ними построже — нет и всё! Эти люди только так и понимают. Им рассусоливать всё равно что с гуся вода. Им строгость нужна, да и дом на вас записан, с Людмилой Степановной, а не на них. И слава Богу, что Виктор Георгиевич тогда отказался, а тоб хлебнули мы с ними. Но это всё пустяки, {{IO}}. Вы на это внимание не тратьте. Главное мне сейчас раздобыть торфу, кирпичей и досок. И тогда мы заживём. А главное — чтоб сарай быстро разобрать и дело с концом. А плотников тут нанять можно и говорят не дорого, тут работы мало у них. Каждый мужик топором помахать может и возьмёт недорого. А строить тут немного, да и я помогу, ведь тоже в плотницком деле мастак — как никак потомственный плотник, хоть и работал всё время кладовщиком. А крышу мы перекроем — любо дорого будет. Это я и один сделаю, чтоб вас не беспокоить, сделаю в лучшем виде. Шиферу раздобыть бы и всё в норме, и рубироида купить. {{IO}}! Если вам не трудно вышлите немного деньжат на покупку вышеназванных материалов, а то я немного поистратился, а мы ужо сочьтёмся. Я бы Машу попросил, но она щас Любане дала на стенку 500, так что я вас прошу, если не трудно. А я потом её попрошу, она вам отдаст.\r\nПередаю всем привет и поздравления,\r\nпишите, не забывайте!\r\nДо свидания.";
            }

            _attachments.Add(new Attachment
            {
                Title = appTitle,
                Text = generatedText
            });

            LstApplications.Items.Refresh();
            TxtAppTitle.Clear();
        }

        private void BtnDeleteApp_Click(object sender, RoutedEventArgs e)
        {
            if (LstApplications.SelectedItem == null)
            {
                MessageBox.Show("Выберите приложение из списка, которое хотите удалить.", "Удаление", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            if (LstApplications.SelectedItem is Attachment selectedApp)
            {
                _attachments.Remove(selectedApp);
                LstApplications.Items.Refresh();
            }
        }

        private void BtnGenerate_Click(object sender, RoutedEventArgs e)
        {
            string fullFio = TxtFullFio.Text.Trim();
            string position = TxtPosition.Text.Trim();
            string organization = TxtOrg.Text.Trim();
            string senderName = TxtSender.Text.Trim();
            string date = DateTime.Now.ToString("dd.MM.yyyy");

            if (string.IsNullOrWhiteSpace(fullFio) ||
                string.IsNullOrWhiteSpace(position) ||
                string.IsNullOrWhiteSpace(organization) ||
                string.IsNullOrWhiteSpace(senderName))
            {
                MessageBox.Show("Ошибка! Все поля (ФИО, Должность, Организация, Отправитель) должны быть заполнены!",
                                "Валидация полей", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }


            string[] words = fullFio.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);

            if (words.Length != 3)
            {
                MessageBox.Show("Ошибка! Поле ФИО должно содержать ровно 3 слова (Фамилия Имя Отчество через пробел).",
                                "Ошибка ввода ФИО", MessageBoxButton.OK, MessageBoxImage.Error);
                return;
            }


            foreach (char c in fullFio)
            {
                if (c != ' ' && c != '-' && !((c >= 'А' && c <= 'я') || c == 'Ё' || c == 'ё'))
                {
                    MessageBox.Show("Ошибка! В поле ФИО разрешена только кириллица. Цифры, латиница и спецсимволы запрещены.",
                                    "Ошибка ввода ФИО", MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }
            }


            foreach (char c in senderName)
            {
                if (c != ' ' && c != '-' && !((c >= 'А' && c <= 'я') || c == 'Ё' || c == 'ё'))
                {
                    MessageBox.Show("Ошибка! В поле 'Имя отправителя' разрешена только кириллица. Цифры, латиница и спецсимволы запрещены.",
                                    "Ошибка ввода отправителя", MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }
            }

            if (_attachments.Count == 0)
            {
                MessageBoxResult result = MessageBox.Show("Вы не добавили ни одного приложения к письму. Сформировать документ без приложений?",
                                                          "Предупреждение", MessageBoxButton.YesNo, MessageBoxImage.Question);
                if (result == MessageBoxResult.No)
                {
                    return;
                }
            }


            string io = words[1];
            if (words.Length >= 3) io += " " + words[2];

            string templateName = "KindLetter.docx";
            string resultName = $"Письмо_{fullFio}.docx";

            try
            {
                if (!File.Exists(templateName))
                {
                    MessageBox.Show("Файл шаблона не найден");
                    return;
                }

                File.Copy(templateName, resultName, true);

                using (WordprocessingDocument doc = WordprocessingDocument.Open(resultName, true))
                {
                    var body = doc.MainDocumentPart.Document.Body;

                    ReplaceText(body, "{{FIO}}", fullFio);
                    ReplaceText(body, "{{POSITION}}", position);
                    ReplaceText(body, "{{ORG}}", organization);
                    ReplaceText(body, "{{IO}}", io);
                    ReplaceText(body, "{{SENDER}}", senderName);
                    ReplaceText(body, "{{DATE}}", date);

                    ProcessAttachmentsList(body);
                    GenerateAttachmentsPages(body, fullFio, io);

                    doc.MainDocumentPart.Document.Save();
                }

                MessageBox.Show($"Документ успешно создан: {resultName}", "Документ создан", MessageBoxButton.OK, MessageBoxImage.Information);
                this.Close();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Произошла ошибка: " + ex.Message);
            }
        }

        private void ReplaceText(Word.Body body, string placeholder, string value)
        {
            foreach (var para in body.Descendants<Word.Paragraph>())
            {
                if (para.InnerText.Contains(placeholder))
                {
                    var runs = para.Elements<Word.Run>().ToList();
                    if (runs.Count > 0)
                    {
                        string fullText = para.InnerText.Replace(placeholder, value ?? "");
                        foreach (var run in runs) run.Remove();

                        Word.Run newRun = new Word.Run();
                        Word.RunProperties runProps = new Word.RunProperties(
                            new Word.RunFonts { Ascii = "Times New Roman", HighAnsi = "Times New Roman", ComplexScript = "Times New Roman" },
                            new Word.FontSize() { Val = "24" }
                        );
                        newRun.AppendChild(runProps);
                        newRun.AppendChild(new Word.Text(fullText));
                        para.AppendChild(newRun);
                    }
                }
            }
        }

        private void ProcessAttachmentsList(Word.Body body)
        {
            foreach (var para in body.Descendants<Word.Paragraph>().ToList())
            {
                if (para.InnerText.Contains("{{ATTACHMENTS_LIST}}"))
                {
                    para.RemoveAllChildren<Word.Run>();

                    if (_attachments.Count == 0) return;

                    InsertTextToPara(para, "Приложения:", true, Word.JustificationValues.Left);

                    Word.Paragraph currentPara = para;
                    for (int i = 0; i < _attachments.Count; i++)
                    {
                        Word.Paragraph newPara = new Word.Paragraph();
                        string listItemText = $"  {i + 1}. {_attachments[i].Title}.";
                        InsertTextToPara(newPara, listItemText, false, Word.JustificationValues.Left);

                        currentPara.InsertAfterSelf(newPara);
                        currentPara = newPara;
                    }
                }
            }
        }

        private void GenerateAttachmentsPages(Word.Body body, string fullFio, string io)
        {
            if (_attachments.Count == 0) return;

            for (int i = 0; i < _attachments.Count; i++)
            {
                Word.Paragraph breakPara = new Word.Paragraph(
                    new Word.Run(new Word.Break { Type = Word.BreakValues.Page })
                );
                body.Append(breakPara);

                Word.Paragraph headerPara = new Word.Paragraph();
                string headerText = _attachments.Count == 1 ? "Приложение" : $"Приложение {i + 1}";
                InsertTextToPara(headerPara, headerText, false, Word.JustificationValues.Right);
                body.Append(headerPara);

                Word.Paragraph titlePara = new Word.Paragraph();
                InsertTextToPara(titlePara, _attachments[i].Title, true, Word.JustificationValues.Center);
                body.Append(titlePara);

                body.Append(new Word.Paragraph());


                string preparedText = _attachments[i].Text
                    .Replace("{{IO}}", io)
                    .Replace("{{FIO}}", fullFio);

                string[] lines = preparedText.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None);
                foreach (var line in lines)
                {
                    Word.Paragraph textPara = new Word.Paragraph();
                    InsertTextToPara(textPara, line, false, Word.JustificationValues.Both);
                    body.Append(textPara);
                }
            }
        }


        private void InsertTextToPara(Word.Paragraph para, string text, bool isBold, Word.JustificationValues align)
        {
            Word.ParagraphProperties paraProps = para.ParagraphProperties ?? new Word.ParagraphProperties();
            paraProps.AppendChild(new Word.Justification { Val = align });
            if (para.ParagraphProperties == null) para.AppendChild(paraProps);

            Word.Run run = new Word.Run();
            Word.RunProperties runProps = new Word.RunProperties(
                new Word.RunFonts { Ascii = "Times New Roman", HighAnsi = "Times New Roman", ComplexScript = "Times New Roman" },
                new Word.FontSize { Val = "24" }
            );

            if (isBold) runProps.AppendChild(new Word.Bold());

            run.AppendChild(runProps);
            run.AppendChild(new Word.Text(text));
            para.AppendChild(run);
        }

        private void Button_Click(object sender, RoutedEventArgs e)
        {
            this.Close();
        }
    }
}